import os, re
H = os.path.dirname(os.path.abspath(__file__))
F = {}
def load(f): F[f] = open(os.path.join(H, f), encoding='utf8').read()
def save():
    for f, s in F.items(): open(os.path.join(H, f), 'w', encoding='utf8').write(s)
def block(f, start):
    """(begin, end) of the top-level statement that starts with `start`."""
    s = F[f]; i = s.index('\n' + start) + 1
    m = re.compile(r'\n(?=\S)').search(s, i)
    return i, (m.start() + 1 if m else len(s))
def rep(f, start, new):
    i, j = block(f, start); F[f] = F[f][:i] + new.strip('\n') + '\n' + F[f][j:]
def after(f, start, new):
    i, j = block(f, start); F[f] = F[f][:j] + new.strip('\n') + '\n' + F[f][j:]
def before(f, start, new):
    i, j = block(f, start); F[f] = F[f][:i] + new.strip('\n') + '\n' + F[f][i:]
def sub(f, a, b):
    assert a in F[f], a[:50]; F[f] = F[f].replace(a, b)

for f in ('content_l1a.py', 'content_l1b.py', 'content_l1c.py', 'content_l1d.py', 'content_l1.py', 'content_a.py'): load(f)
